-- Core tables for agents, workflows, runs and their trace (DESIGN section 4).
-- All ids are UUIDv7 text generated by the application. All times are UTC.

CREATE TABLE agents (
    id                TEXT PRIMARY KEY,
    name              TEXT NOT NULL,
    role              TEXT NOT NULL DEFAULT '',
    system_prompt     TEXT NOT NULL DEFAULT '',
    model             TEXT NOT NULL,
    effort            TEXT NOT NULL DEFAULT 'medium',
    max_tokens        INT  NOT NULL DEFAULT 8192,
    tool_allowlist    JSONB NOT NULL DEFAULT '[]',
    interaction_rules JSONB NOT NULL DEFAULT '{}',
    limits            JSONB NOT NULL DEFAULT '{}',
    guardrails        JSONB NOT NULL DEFAULT '{}',
    memory_policy     JSONB NOT NULL DEFAULT '{}',
    channels          JSONB NOT NULL DEFAULT '[]',
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at        TIMESTAMPTZ
);

CREATE TABLE workflows (
    id           TEXT PRIMARY KEY,
    name         TEXT NOT NULL,
    description  TEXT NOT NULL DEFAULT '',
    definition   JSONB NOT NULL,
    version      INT  NOT NULL DEFAULT 1,
    template_key TEXT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    deleted_at   TIMESTAMPTZ
);
CREATE UNIQUE INDEX workflows_template_key_idx ON workflows (template_key) WHERE template_key IS NOT NULL AND deleted_at IS NULL;

CREATE TABLE runs (
    id                   TEXT PRIMARY KEY,
    workflow_id          TEXT NOT NULL REFERENCES workflows (id),
    workflow_version     INT  NOT NULL,
    workflow_snapshot    JSONB NOT NULL,
    trigger              TEXT NOT NULL,            -- manual | schedule | channel | eval
    trigger_ref          TEXT,                     -- schedule id, conversation id, eval case id
    status               TEXT NOT NULL,            -- queued | running | waiting_approval | succeeded | failed | cancelled | timed_out
    input                JSONB NOT NULL DEFAULT '{}',
    state                JSONB NOT NULL DEFAULT '{}',
    limits               JSONB NOT NULL,
    current_node         TEXT,
    resume_node_visit_id TEXT,
    step_count           INT  NOT NULL DEFAULT 0,
    tool_call_count      INT  NOT NULL DEFAULT 0,
    attempt              INT  NOT NULL DEFAULT 1,
    cancel_requested     BOOLEAN NOT NULL DEFAULT false,
    cancel_by            TEXT,
    failure_reason       TEXT,
    cost_usd_micros      BIGINT NOT NULL DEFAULT 0,
    input_tokens         BIGINT NOT NULL DEFAULT 0,
    output_tokens        BIGINT NOT NULL DEFAULT 0,
    cache_read_tokens    BIGINT NOT NULL DEFAULT 0,
    cache_write_tokens   BIGINT NOT NULL DEFAULT 0,
    paused_at            TIMESTAMPTZ,
    paused_total_ms      BIGINT NOT NULL DEFAULT 0,
    created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at           TIMESTAMPTZ,
    finished_at          TIMESTAMPTZ,
    updated_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX runs_status_idx ON runs (status, created_at);
CREATE INDEX runs_workflow_idx ON runs (workflow_id, created_at DESC);

CREATE TABLE run_nodes (
    id                   TEXT PRIMARY KEY,
    run_id               TEXT NOT NULL REFERENCES runs (id) ON DELETE CASCADE,
    node_id              TEXT NOT NULL,
    agent_id             TEXT,
    visit                INT  NOT NULL DEFAULT 1,
    iteration            INT  NOT NULL DEFAULT 0,
    status               TEXT NOT NULL,            -- pending | running | waiting_approval | succeeded | failed | skipped
    messages             JSONB NOT NULL DEFAULT '[]',
    pending_tool_results JSONB,
    output               JSONB,
    failure_reason       TEXT,
    started_at           TIMESTAMPTZ,
    finished_at          TIMESTAMPTZ
);
CREATE INDEX run_nodes_run_idx ON run_nodes (run_id, started_at);

CREATE TABLE model_calls (
    id                 TEXT PRIMARY KEY,
    run_id             TEXT NOT NULL REFERENCES runs (id) ON DELETE CASCADE,
    run_node_id        TEXT NOT NULL REFERENCES run_nodes (id) ON DELETE CASCADE,
    provider           TEXT NOT NULL,
    model              TEXT NOT NULL,
    request_id         TEXT,
    stop_reason        TEXT,
    input_tokens       BIGINT NOT NULL DEFAULT 0,
    output_tokens      BIGINT NOT NULL DEFAULT 0,
    cache_read_tokens  BIGINT NOT NULL DEFAULT 0,
    cache_write_tokens BIGINT NOT NULL DEFAULT 0,
    cost_usd_micros    BIGINT NOT NULL DEFAULT 0,
    duration_ms        BIGINT NOT NULL DEFAULT 0,
    attempt            INT  NOT NULL DEFAULT 1,
    error              TEXT,
    started_at         TIMESTAMPTZ NOT NULL,
    finished_at        TIMESTAMPTZ
);
CREATE INDEX model_calls_run_idx ON model_calls (run_id, started_at);

CREATE TABLE tool_calls (
    id              TEXT PRIMARY KEY,
    run_id          TEXT NOT NULL REFERENCES runs (id) ON DELETE CASCADE,
    run_node_id     TEXT NOT NULL REFERENCES run_nodes (id) ON DELETE CASCADE,
    model_call_id   TEXT REFERENCES model_calls (id) ON DELETE SET NULL,
    tool_use_id     TEXT NOT NULL,
    tool_name       TEXT NOT NULL,
    input           JSONB NOT NULL,
    output          JSONB,
    is_error        BOOLEAN NOT NULL DEFAULT false,
    status          TEXT NOT NULL,            -- executed | awaiting_approval | approved | rejected | blocked | expired | failed
    idempotency_key TEXT,
    attempt         INT  NOT NULL DEFAULT 1,
    duration_ms     BIGINT NOT NULL DEFAULT 0,
    started_at      TIMESTAMPTZ,
    finished_at     TIMESTAMPTZ
);
CREATE INDEX tool_calls_run_idx ON tool_calls (run_id, started_at);

CREATE TABLE side_effects (
    idempotency_key TEXT PRIMARY KEY,
    tool_name       TEXT NOT NULL,
    run_id          TEXT NOT NULL,
    tool_call_id    TEXT NOT NULL,
    result          JSONB,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE approvals (
    id           TEXT PRIMARY KEY,
    run_id       TEXT NOT NULL REFERENCES runs (id) ON DELETE CASCADE,
    run_node_id  TEXT NOT NULL REFERENCES run_nodes (id) ON DELETE CASCADE,
    tool_call_id TEXT REFERENCES tool_calls (id) ON DELETE CASCADE,
    kind         TEXT NOT NULL,                -- tool | node
    node_id      TEXT NOT NULL,
    message      TEXT NOT NULL DEFAULT '',
    status       TEXT NOT NULL,                -- pending | approved | rejected | expired
    requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    decided_at   TIMESTAMPTZ,
    decided_by   TEXT,
    reason       TEXT,
    expires_at   TIMESTAMPTZ NOT NULL
);
CREATE INDEX approvals_status_idx ON approvals (status, requested_at);

CREATE TABLE agent_messages (
    id         TEXT PRIMARY KEY,
    run_id     TEXT NOT NULL REFERENCES runs (id) ON DELETE CASCADE,
    from_node  TEXT NOT NULL,
    to_node    TEXT NOT NULL,
    payload    JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX agent_messages_run_idx ON agent_messages (run_id, created_at);

CREATE TABLE spans (
    id         TEXT PRIMARY KEY,
    run_id     TEXT NOT NULL REFERENCES runs (id) ON DELETE CASCADE,
    parent_id  TEXT,
    kind       TEXT NOT NULL,                  -- run | node | model_call | tool_call | approval_wait
    name       TEXT NOT NULL,
    started_at TIMESTAMPTZ NOT NULL,
    ended_at   TIMESTAMPTZ,
    attrs      JSONB NOT NULL DEFAULT '{}'
);
CREATE INDEX spans_run_idx ON spans (run_id, started_at);

CREATE TABLE workspace_files (
    run_id     TEXT NOT NULL REFERENCES runs (id) ON DELETE CASCADE,
    path       TEXT NOT NULL,
    content    TEXT NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (run_id, path)
);

-- Durable event log behind SSE so clients can resume with Last-Event-ID.
CREATE TABLE run_events (
    seq        BIGSERIAL PRIMARY KEY,
    run_id     TEXT,
    event      TEXT NOT NULL,
    data       JSONB NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX run_events_run_idx ON run_events (run_id, seq);
